/**
 * OPEN FOLDERS FROM OTHER APPS (#393): Windows' folder verb runs the helper,
 * which starts Prism with `--win-e=<id> --browse=<folder>`. Prism answers on
 * the helper's pipe ("started", then the id once the browser shows) and the
 * Explorer lands on that folder: in the pinned Explorer tab when there is one,
 * in a new one when the strip is empty. The pipe here is the helper's
 * stand-in; nothing is registered with Windows.
 */
/** The helper's stand-in: its pipe for request `id`, and every line Prism
 *  writes down it ("<id> started", then "<id>" once the folder shows). */
function winEHelper(id) {
  const lines = []
  let text = ''
  /** When Prism let go of the pipe (ms since the epoch), the helper's cue
   *  to fall back to File Explorer unless the ready line came first. */
  const pipe = { closedAt: 0 }
  const server = createServer((socket) => {
    socket.on('data', (chunk) => {
      text += chunk.toString('utf8')
      let at
      while ((at = text.indexOf('\n')) >= 0) {
        lines.push(text.slice(0, at))
        text = text.slice(at + 1)
      }
    })
    socket.on('close', () => (pipe.closedAt = Date.now()))
    socket.on('error', () => {})
  })
  return new Promise((resolve) => server.listen(`\\\\.\\pipe\\PrismWinE.${id}`, () => resolve({ lines, server, pipe })))
}

async function folderOpenScenario(fixtures) {
  console.log('a folder opened from another app lands in the Explorer (#393)')
  const dir = join(fixtures, 'folderopen', 'a folder & more')
  mkdirSync(dir, { recursive: true })
  writeFileSync(join(dir, 'inside.txt'), 'here\n')
  const helper = winEHelper
  for (const [label, tabs] of [
    ['the pinned Explorer', { active: 0, tabs: [explorerTab('fixture-explorer', fixtures, fixtures, true)] }],
    ['an empty strip', { active: 0, tabs: [] }]
  ]) {
    const id = randomUUID()
    const { lines, server } = await helper(id)
    let app
    try {
      writeTabs(tabs)
      app = await startApp({ args: [`--win-e=${id}`, `--browse=${dir}`], env: NO_INDEX })
      const win = await app.firstWindow()
      await offscreen(app)
      ok(
        await until(async () => (await zipWhere(win).catch(() => '')).toLowerCase() === dir.toLowerCase(), 20000),
        `${label}: the Explorer shows the folder (${await zipWhere(win).catch(() => '?')})`
      )
      ok(await until(async () => lines.includes(id), 15000), `${label}: the helper got started and ready (${lines.map((l) => l.replace(id, '<id>')).join(' / ')})`)
      ok(lines[0] === `${id} started`, `${label}: "started" came first`)
    } finally {
      await app?.close().catch(() => {})
      server.close()
    }
  }
}

/** Prism's own MAIN processes on the e2e profile: an electron.exe whose
 *  command line names the profile and that is no Chromium child (those carry
 *  `--type=`). The retired Win+E windows were one each (their profiles sat
 *  under this one). -1 when PowerShell cannot say. */
function prismMainCount() {
  try {
    return (
      Number(
        powershell(
          `(Get-CimInstance Win32_Process -Filter "Name='electron.exe'" | Where-Object { $_.CommandLine -like '*${PROFILE_NAME}*' -and $_.CommandLine -notlike '*--type=*' } | Measure-Object).Count`
        ).trim()
      ) || 0
    )
  } catch {
    return -1
  }
}

/** A second launch carrying a Win+E request, the way the helper starts
 *  Prism (`--win-e=<id>`, and `--browse=<folder>` from the folder verb): it
 *  hands the request to the running Prism and exits. */
async function winELaunch(id, browse) {
  const child = spawn(
    electronPath,
    [MAIN, `--user-data-dir=${PROFILE}`, '--e2e', `--win-e=${id}`, ...(browse ? [`--browse=${browse}`] : [])],
    { stdio: 'ignore' }
  )
  await new Promise((done) => {
    child.on('exit', done)
    setTimeout(done, 6000) // it should quit on its own; never hang the suite
  })
}

/**
 * WIN+E WHILE PRISM RUNS OPENS A WINDOW IN THE SAME PROCESS (tab tear-off
 * step 2, 2026-10-29; review finding #12). It used to start a whole second
 * Prism on a profile of its own (`explorerWindow.ts`, retired). Now the
 * running Prism opens a new window: the folder verb's at the folder it
 * names, a plain Win+E's at "Folder for new tabs". Its page answers the
 * helper as the second process's did ("started" at once, the id once the
 * folder shows), there is never a second Prism process, and the first
 * window keeps its own folder. The cold start's route is folderOpen's.
 */
async function folderOpenRunningScenario(fixtures) {
  console.log('Win+E and the folder verb while Prism runs open a window in the same process')
  const dir = join(fixtures, 'folderopen', 'a folder & more')
  mkdirSync(dir, { recursive: true })
  writeFileSync(join(dir, 'inside.txt'), 'here\n')
  const newTabs = join(fixtures, 'folderopen', 'new tabs here')
  mkdirSync(newTabs, { recursive: true })
  writeFileSync(join(newTabs, 'fresh.txt'), 'new\n')
  // A plain Win+E's window lands at the folder for new tabs; put back after.
  seedPreferences(PROFILE, { 'prism.newtab.mode': 'folder', 'prism.newtab.folder': newTabs })
  writeTabs({ active: 0, tabs: [explorerTab('fixture-explorer', fixtures, fixtures, true)] })
  const servers = []
  let app
  try {
    app = await startApp({ env: NO_INDEX })
    const win = await app.firstWindow()
    await win.waitForLoadState('domcontentloaded')
    await offscreen(app)
    ok(
      await until(async () => (await e2eWindows(app)).some((w) => w.first && w.restored), 15000),
      'Prism is up: one window, restored'
    )
    ok(await until(() => prismMainCount() === 1, 8000, 500), `one Prism process to begin with (${prismMainCount()})`)
    for (const [label, browse, expected] of [
      ['the folder verb', dir, dir],
      ['a plain Win+E', null, newTabs]
    ]) {
      const id = randomUUID()
      const { lines, server } = await winEHelper(id)
      servers.push(server)
      const before = (await e2eWindows(app)).length
      const appeared = app.waitForEvent('window', { timeout: 20000 }).catch(() => null)
      await winELaunch(id, browse)
      const page = await appeared
      ok(!!page, `${label}: a new window opened in the running Prism`)
      if (!page) continue
      await page.waitForLoadState('domcontentloaded').catch(() => {})
      await offscreen(app)
      let list = []
      ok(
        await until(async () => {
          list = await e2eWindows(app)
          return list.length === before + 1
        }, 10000),
        `${label}: one window more (${list.length})`
      )
      ok(list.some((w) => w.winE === id && !w.first), `${label}: main holds it as the window for this request`)
      ok(
        await until(async () => (await zipWhere(page).catch(() => '')).toLowerCase() === expected.toLowerCase(), 20000),
        `${label}: the new window shows ${basename(expected)} (${await zipWhere(page).catch(() => '?')})`
      )
      ok(
        await until(async () => lines.includes(id), 15000),
        `${label}: the helper got started and ready (${lines.map((l) => l.replace(id, '<id>')).join(' / ')})`
      )
      ok(lines[0] === `${id} started`, `${label}: "started" came first`)
      ok(await until(() => prismMainCount() === 1, 8000, 500), `${label}: still ONE Prism process, no second one (${prismMainCount()})`)
      ok(
        (await zipWhere(win).catch(() => '')).toLowerCase() === fixtures.toLowerCase(),
        `${label}: the first window keeps its own folder (${await zipWhere(win).catch(() => '?')})`
      )
    }
  } finally {
    await app?.close().catch(() => {})
    for (const server of servers) server.close()
    seedPreferences(PROFILE, { 'prism.newtab.mode': 'folder', 'prism.newtab.folder': join(ROOT, '.e2e', 'fixtures') })
  }
}

/**
 * WIN+E WHILE PRISM RUNS, THE RISKY PATHS (step 2 review, 2026-10-29):
 * - two presses at once: two requests pending and two windows loading
 *   together, each answered by its own window;
 * - a window closed before it answers lets go of the helper's pipe at once
 *   (it opened File Explorer 45 s later, with no visible cause);
 * - a Win+E window focused last never becomes what the next cold start
 *   opens: the first window's strip leads the session file after a quit.
 */
async function winERunningEdgesScenario(fixtures) {
  console.log('Win+E while Prism runs: two at once, a window closed before it answers, the session after a quit')
  const dir = join(fixtures, 'folderopen', 'a folder & more')
  mkdirSync(dir, { recursive: true })
  writeFileSync(join(dir, 'inside.txt'), 'here\n')
  writeTabs({ active: 0, tabs: [explorerTab('fixture-explorer', fixtures, fixtures, true)] })
  const servers = []
  let app
  try {
    app = await startApp({ env: NO_INDEX })
    const win = await app.firstWindow()
    await win.waitForLoadState('domcontentloaded')
    await offscreen(app)
    ok(
      await until(async () => (await e2eWindows(app)).some((w) => w.first && w.restored), 15000),
      'Prism is up: one window, restored'
    )
    // Two presses at once.
    const pair = []
    for (let i = 0; i < 2; i++) {
      const id = randomUUID()
      const helper = await winEHelper(id)
      servers.push(helper.server)
      pair.push({ id, ...helper })
    }
    await Promise.all(pair.map(({ id }) => winELaunch(id, dir)))
    let list = []
    ok(
      await until(async () => {
        list = await e2eWindows(app)
        await offscreen(app)
        return pair.every(({ id }) => list.some((w) => w.winE === id))
      }, 20000),
      `two presses at once: a window for each (${list.length} windows)`
    )
    for (const [i, { id, lines }] of pair.entries())
      ok(
        await until(() => lines.includes(id), 20000),
        `press ${i + 1}: answered by its own window (${lines.map((l) => l.replace(id, '<id>')).join(' / ')})`
      )
    // A window closed before it answers. Closed from main the moment main
    // holds it, before its page can load; if the page still won the race the
    // check says so rather than passing on nothing.
    const id = randomUUID()
    const helper = await winEHelper(id)
    servers.push(helper.server)
    const launched = winELaunch(id, dir)
    let closedAt = 0
    await until(async () => {
      closedAt = await app
        .evaluate(({ BrowserWindow }, request) => {
          const r = globalThis.__e2eWindows().find((w) => w.winE === request)
          if (!r) return 0
          BrowserWindow.fromId(r.id)?.destroy()
          return Date.now()
        }, id)
        .catch(() => 0)
      return closedAt > 0
    }, 15000, 20)
    await launched
    ok(closedAt > 0, 'a window closed before it answers: main held one for the request')
    ok(
      await until(() => helper.pipe.closedAt > 0, 5000, 50),
      `a window closed before it answers: the helper's pipe is let go at once (${helper.pipe.closedAt ? helper.pipe.closedAt - closedAt + ' ms' : 'still open'}; ${helper.lines.includes(id) ? 'the page had answered first' : 'unanswered'})`
    )
    // The session after a quit: a Win+E window focused LAST still ranks
    // below the first window. The windows are unfocusable under --e2e, so the
    // focus is main's own event, as Windows would send it.
    const { id: lastId } = pair[1]
    await app.evaluate(({ BrowserWindow }, request) => {
      const r = globalThis.__e2eWindows().find((w) => w.winE === request)
      if (r) BrowserWindow.fromId(r.id)?.emit('focus')
    }, lastId)
    await sleep(700) // tabs.json saves on a 400ms debounce
    // A REAL quit: the harness's close is app.exit, which skips before-quit,
    // so every window would look closed one by one and drop its entry.
    await quitForLog(app)
    app = null
    const saved = sessionFile()
    ok(
      (saved?.windows?.length ?? 0) >= 3,
      `the quit keeps every window's entry (${saved?.windows?.length ?? 'no file'})`
    )
    ok(
      !!saved?.tabs?.some((t) => t.id === 'fixture-explorer'),
      `a Win+E window focused last does not lead the session file (${(saved?.tabs ?? []).map((t) => t.root).join(', ')})`
    )
  } finally {
    await app?.close().catch(() => {})
    for (const server of servers) server.close()
  }
}

/**
 * LOCKED, DAMAGED AND TEMP (#300): a ZipCrypto member asks once and again on a
 * wrong password; a damaged zip says so and keeps the list where it was;
 * every member opened lands under the run's `prism-members` folder, nothing in
 * `%TEMP%\prism-zip-*`, and the run's folder is gone after quit.
 */
async function zipLockedScenario(fixtures) {
  console.log('locked, damaged and temp (#300)')
  const dir = join(fixtures, 'ziplocked')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  copyFileSync(join(ROOT, 'src', 'main', 'fixtures', 'crypto.zip'), join(dir, 'crypto.zip'))
  writeFileSync(join(dir, 'broken.zip'), Buffer.concat([Buffer.from('PK\u0003\u0004'), Buffer.alloc(64, 7)]))
  writeFileSync(join(dir, 'notes.txt'), 'beside\n')
  const before = new Set(readdirSync(tmpdir()).filter((n) => n.startsWith('prism-zip-')))
  const { app, win } = await launchWith(NO_INDEX, join(dir, 'notes.txt'))
  let runDir
  try {
    await explorerAt(win, dir)
    // Damaged: the error line, and the list stays where it was.
    await zipRow(win, 'broken.zip').dblclick()
    ok(await until(async () => /can't be read/i.test((await win.locator('.browse-list-area').textContent()) ?? ''), 10000), 'a damaged zip says it cannot be read')
    await win.locator('[data-testid="browse-list"]').focus()
    // Locked: entering lists; opening a member asks.
    await zipGo(win, join(dir, 'crypto.zip'), async () => (await win.locator('[data-archive-strip]').count()) === 1)
    const first = (await zipRows(win)).find((p) => /\.\w+$/.test(p))
    ok(!!first, `the locked zip lists its members (${first})`)
    await zipRow(win, first.replace(/^.*\\/, '')).click()
    ok(await until(async () => (await win.locator('input[aria-label="Archive password"]').count()) === 1, 10000), 'a locked member asks for the password')
    await win.locator('input[aria-label="Archive password"]').fill('wrong-one')
    await win.keyboard.press('Enter')
    ok(await until(async () => /didn't open/.test((await win.textContent('body')) ?? ''), 10000), 'a wrong one asks again, saying so')
    await win.locator('input[aria-label="Archive password"]').fill('letmein')
    await win.keyboard.press('Enter')
    ok(await until(async () => (await win.locator('input[aria-label="Archive password"]').count()) === 0 && (await win.locator('[data-member-gate]').count()) === 0, 10000), 'the right one opens it')
    const members = join(tmpdir(), 'prism-members')
    const runs = existsSync(members) ? readdirSync(members) : []
    ok(runs.length >= 1, `members land under the run's prism-members folder (${runs.join(', ')})`)
    const after = readdirSync(tmpdir()).filter((n) => n.startsWith('prism-zip-') && !before.has(n))
    ok(after.length === 0, `nothing new in %TEMP%\\prism-zip-* (${after.join(', ')})`)
    runDir = runs.map((r) => join(members, r))
  } finally {
    await app.close()
  }
  await sleep(1500)
  const left = (runDir ?? []).filter((d) => existsSync(d))
  ok(left.length === 0, `the run's member folder is gone after quit (${left.join(', ')})`)
}

/* ----- the diagnostics log (#322) ----- */

/** The diagnostics log of the shared profile, one object per line (a line
 *  that is not JSON comes back as `{ bad }`, so a scenario can say so). */
const DIAG_DIR = join(PROFILE, 'logs')
function readDiag() {
  try {
    return readFileSync(join(DIAG_DIR, 'diag.jsonl'), 'utf8')
      .split('\n')
      .filter(Boolean)
      .map((l) => {
        try {
          return JSON.parse(l)
        } catch {
          return { bad: l }
        }
      })
  } catch {
    return []
  }
}
/** Lines land in batches (the page's every 250 ms, the writer's every 250
 *  ms), so every look waits for its line. */
const diagHas = (fn, ms = 10000) => until(() => readDiag().find(fn) ?? false, ms, 100)

/* ---------- THE PROPERTIES WINDOW (owner, 2026-10-12) ---------- */

/** Is there an ffmpeg to make the media fixtures with? */
const HAS_FFMPEG = (() => {
  try {
    execFileSync(FFMPEG, ['-version'], { stdio: 'ignore', windowsHide: true })
    return true
  } catch {
    return false
  }
})()

/** The open Properties window's facts, label to value. */
const propsFacts = (win) =>
  win.evaluate(() =>
    Object.fromEntries(
      [...document.querySelectorAll('[data-props-window] dt')].map((dt) => [dt.textContent ?? '', dt.nextElementSibling?.textContent ?? ''])
    )
  )

/** Right-click a row of the Explorer and pick Properties. */
async function openRowProps(win, suffix) {
  await zipRow(win, suffix).click({ button: 'right' })
  await win.locator('[role="menu"] [role="menuitem"]:has-text("Properties")').click()
  return until(async () => (await win.locator('[data-props-window]').count()) === 1, 8000)
}

/** Close, the window's own button, and the window is gone. */
async function closeProps(win) {
  await win.locator('[data-props-window] button[data-primary="true"]').click()
  return until(async () => (await win.locator('[data-props-window]').count()) === 0, 5000)
}

/**
 * THE PROPERTIES WINDOW, PER KIND (owner, 2026-10-12; spec
 * `docs/superpowers/specs/2026-10-12-properties-window-design.md`, Tests).
 * Opened from the Explorer's row menu on a CRLF text file, a .py, a folder,
 * a PNG, and (made with the bundled ffmpeg) a film and two songs, one with
 * its cover and one without (the sound bars, audio option D); then the C:
 * drive from This PC: its donut, the legend, a slice's tooltip naming a
 * legend row, Disk Cleanup (never clicked: it opens Windows' own cleaner)
 * and Close. The checksum is held to Node's own SHA-256.
 */
async function propertiesWindowScenario(fixtures) {
  console.log('properties window (2026-10-12)')
  const dir = join(fixtures, 'propswin')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(join(dir, 'sub'), { recursive: true })
  writeFileSync(join(dir, 'sub', 'inside.txt'), 'inside the folder\n')
  const notes = join(dir, 'notes.txt')
  writeFileSync(notes, 'First line of the notes\r\nSecond line\r\nThird and last line\r\n')
  writeFileSync(join(dir, 'hello.py'), 'def hello():\n    return 42\n')
  writeFileSync(join(dir, 'pic.png'), ZIP_PNG)
  let media = HAS_FFMPEG
  if (media) {
    const ff = (args) => execFileSync(FFMPEG, ['-y', '-loglevel', 'error', ...args], { windowsHide: true, stdio: 'ignore' })
    try {
      // libopenh264: the bundled ffmpeg is the LGPL build (see fixtures.mjs).
      ff(['-f', 'lavfi', '-i', 'testsrc=duration=1:size=320x240:rate=10', '-pix_fmt', 'yuv420p', '-c:v', 'libopenh264', '-b:v', '300k', join(dir, 'clip.mp4')])
      const cover = join(fixtures, 'propswin-cover.png')
      ff(['-f', 'lavfi', '-i', 'testsrc=size=96x96', '-frames:v', '1', cover])
      ff(['-f', 'lavfi', '-i', 'sine=frequency=440:duration=1', '-i', cover, '-map', '0:a', '-map', '1:v', '-c:a', 'flac', '-c:v', 'png', '-disposition:v', 'attached_pic', join(dir, 'song-cover.flac')])
      ff(['-f', 'lavfi', '-i', 'sine=frequency=440:duration=1', '-c:a', 'flac', join(dir, 'song-plain.flac')])
      rmSync(cover, { force: true })
    } catch (e) {
      media = false
      console.log(`  (ffmpeg could not make the media fixtures, so the film and song checks are skipped: ${e.message})`)
    }
  } else console.log(`  (no ffmpeg found (tried ${FFMPEG}), so the film and song checks are skipped)`)

  // The drive's donut sizes its folders from the search index; this machine's
  // own Everything has C: indexed already, which a fresh e2e index has not.
  const { app, win } = await launchWith({ PRISM_E2E_EXISTING_INDEX: '1' }, notes)
  try {
    await explorerAt(win, dir)

    // 1. A TEXT FILE: the language, the encoding, the line endings, the counts.
    ok(await openRowProps(win, 'notes.txt'), 'text: Properties opens from the row menu')
    const text = await until(async () => {
      const f = await propsFacts(win)
      return 'Lines' in f && 'Encoding' in f ? f : null
    }, 8000)
    ok(!!text && 'Language' in text, `text: a Language row (${text?.Language})`)
    ok(/^UTF-8/.test(text?.Encoding ?? ''), `text: the encoding is UTF-8 (${text?.Encoding})`)
    ok(/^CRLF/.test(text?.['Line endings'] ?? ''), `text: the line endings are CRLF (${text?.['Line endings']})`)
    ok(text?.Lines === '3', `text: three lines (${text?.Lines})`)

    // The checksum row: Compute, the hash, and it is Node's own SHA-256.
    await win.locator('[data-props-window] [data-props-checksum] button:has-text("Compute")').click()
    const hash = await until(() => win.locator('[data-props-hash]').getAttribute('data-props-hash', { timeout: 200 }).catch(() => null), 10000)
    const want = createHash('sha256').update(readFileSync(notes)).digest('hex')
    ok(hash === want, `checksum: Compute gives Node's SHA-256 (${hash})`)
    ok((await win.locator('[data-props-checksum="done"] [data-props-copy]').count()) === 1, 'checksum: with a copy button')
    await win.screenshot({ path: join(SHOTS, 'props-text.png') })
    ok(await closeProps(win), 'text: Close closes')

    // 2. CODE: the language by name.
    await openRowProps(win, 'hello.py')
    const py = await until(async () => {
      const f = await propsFacts(win)
      return 'Lines' in f ? f : null
    }, 8000)
    ok(/Python/.test(py?.Language ?? ''), `code: the language is Python (${py?.Language})`)
    await closeProps(win)

    // 3. A FOLDER: its own dates, no newest file, Close the only button.
    await openRowProps(win, '\\sub')
    const folder = await until(async () => {
      const f = await propsFacts(win)
      return 'Created' in f ? f : null
    }, 8000)
    ok(!!folder && 'Created' in folder && 'Opened' in folder, `folder: Created and Opened rows (${Object.keys(folder ?? {}).join(', ')})`)
    ok(!/Newest file/.test((await win.locator('[data-props-window]').textContent()) ?? ''), 'folder: no Newest file')
    const buttons = await win
      .locator('[data-props-window] button:not([data-props-copy])')
      .evaluateAll((els) => els.map((b) => b.textContent?.trim() ?? ''))
    ok(buttons.join('|') === 'Close', `folder: Close is the only button (${buttons.join(', ')})`)
    await win.screenshot({ path: join(SHOTS, 'props-folder.png') })
    await closeProps(win)

    // 4. A PICTURE: the picture across the top.
    await openRowProps(win, 'pic.png')
    ok(await until(async () => (await win.locator('[data-props-body="photo"] img').count()) === 1, 5000), 'photo: the picture is the header')
    await closeProps(win)

    if (media) {
      // 5. A FILM: a frame on top, the resolution row.
      await openRowProps(win, 'clip.mp4')
      const film = await until(async () => {
        const f = await propsFacts(win)
        return 'Resolution' in f ? f : null
      }, 15000)
      ok(!!film, `video: a Resolution row (${film?.Resolution})`)
      ok(await until(async () => (await win.locator('[data-props-body="video"] img').count()) === 1, 15000), 'video: a frame is the header')
      await win.screenshot({ path: join(SHOTS, 'props-video.png') })
      await closeProps(win)

      // 6. SONGS: the file's own cover, or the sound bars on its tile.
      await openRowProps(win, 'song-cover.flac')
      ok(await until(async () => (await win.locator('[data-props-cover="art"] img').count()) === 1, 15000), 'song: the cover art is the header')
      await closeProps(win)
      await openRowProps(win, 'song-plain.flac')
      ok(await until(async () => (await win.locator('[data-props-cover="bars"] svg').count()) === 1, 15000), 'song without a cover: the sound bars tile')
      await win.screenshot({ path: join(SHOTS, 'props-song.png') })
      await closeProps(win)
    }

    // On the second desktop (tools/e2e/hidden.mjs) this machine's Everything is
    // out of reach: its IPC is a window on the OWNER's desktop, and a window on
    // another desktop cannot be found (measured 2026-10-28: 0 slices). The
    // drive step needs that index, so it is skipped there, and says so.
    if (process.env.PRISM_E2E_DESKTOP === 'hidden') {
      console.log("  (on the hidden desktop this PC's Everything cannot be reached, so the drive donut checks are skipped)")
      return
    }
    // 7. THE DRIVE, from This PC. The index answers when it has C:; until it
    // does the window asks again, each opening its own question.
    const cDrive = win.locator('.folder-browser .browse-places section[aria-label="This PC"] .browse-drive[title="C:\\\\"]')
    ok(await until(async () => (await cDrive.count()) === 1, 15000), 'drive: C: is in This PC')
    let slices = 0
    const end = Date.now() + 90000
    while (Date.now() < end) {
      await cDrive.click({ button: 'right' })
      await win.locator('[role="menu"] [role="menuitem"]:has-text("Properties")').click()
      await until(async () => (await win.locator('[data-props-body="drive"]').count()) === 1, 8000)
      // Main's answer is in once the ring stops saying Reading.
      await until(async () => (await win.locator('[data-props-body="drive"] .donut-pair').count()) === 1, 20000)
      slices = await win.locator('[data-props-body="drive"] svg circle.donut-slice').count()
      if (slices > 0) break
      await closeProps(win)
      await sleep(3000)
    }
    ok((await win.locator('[data-props-body="drive"] svg').count()) >= 1 && slices > 0, `drive: the donut draws its folders (${slices} slices)`)
    const legend = await win.locator('[data-props-body="drive"] .donut-row .donut-name').evaluateAll((els) => els.map((e) => e.textContent ?? ''))
    ok(legend.length > 0, `drive: the legend has rows (${legend.length})`)
    // A point on the ring over a slice: the circle's own box is the whole
    // ring, and its middle is the hole.
    const spot = await win.evaluate(() => {
      const svg = document.querySelector('[data-props-body="drive"] .donut-ring svg')
      if (!svg) return null
      const r = svg.getBoundingClientRect()
      const cx = r.left + r.width / 2
      const cy = r.top + r.height / 2
      const radius = (r.width / 150) * 65 // the ring's middle (DriveDonut: (150 - 20) / 2)
      for (let a = 0; a < 360; a += 2) {
        const x = cx + radius * Math.cos((a * Math.PI) / 180)
        const y = cy + radius * Math.sin((a * Math.PI) / 180)
        if (document.elementFromPoint(x, y)?.classList.contains('donut-slice')) return { x, y }
      }
      return null
    })
    ok(!!spot, 'drive: a slice is under the pointer somewhere on the ring')
    if (spot) {
      await win.mouse.move(spot.x - 4, spot.y - 4)
      await win.mouse.move(spot.x, spot.y)
      const tip = await until(() => win.locator('.donut-tip b').textContent({ timeout: 200 }).catch(() => null), 3000)
      ok(!!tip && legend.includes(tip), `drive: the slice's tooltip names a legend row (${tip})`)
      ok((await win.locator('[data-props-body="drive"] .donut-row[data-hot]').count()) === 1, 'drive: and lights that row')
      await sleep(200) // the tooltip fades in over 120 ms; the shot shows it settled
      await win.screenshot({ path: join(SHOTS, 'props-drive.png') })
    }
    ok((await win.locator('[data-props-window] button:has-text("Disk Cleanup")').count()) === 1, 'drive: a Disk Cleanup button')
    ok(await closeProps(win), 'drive: Close closes')
  } finally {
    await app.close().catch(() => {})
    // Its files must not outlive it: phoneDocs counts the fixtures' .py files.
    rmSync(dir, { recursive: true, force: true })
  }
}

/* ---------- THE IMAGE PACK (#78, owner, 2026-11-01) ---------- */

/** A PNG of `w` by `h` RGBA pixels, `px(x, y)` giving [r, g, b, a]. */
function rgbaPng(w, h, px) {
  const chunk = (type, data) => {
    const len = Buffer.alloc(4)
    len.writeUInt32BE(data.length)
    const body = Buffer.concat([Buffer.from(type, 'ascii'), data])
    const crc = Buffer.alloc(4)
    crc.writeUInt32BE(zlibCrc32(body) >>> 0)
    return Buffer.concat([len, body, crc])
  }
  const ihdr = Buffer.alloc(13)
  ihdr.writeUInt32BE(w, 0)
  ihdr.writeUInt32BE(h, 4)
  ihdr[8] = 8
  ihdr[9] = 6 // RGBA
  const rows = Buffer.alloc((w * 4 + 1) * h)
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) Buffer.from(px(x, y)).copy(rows, y * (w * 4 + 1) + 1 + x * 4)
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(rows)),
    chunk('IEND', Buffer.alloc(0))
  ])
}

/** A transparent PNG: clear (black under the alpha, as most are) with an
 *  opaque red square in the middle. */
const clearPng = () => rgbaPng(64, 64, (x, y) => (x >= 16 && x < 48 && y >= 16 && y < 48 ? [220, 30, 30, 255] : [0, 0, 0, 0]))

/**
 * A camera's EXIF and a Display P3 ICC profile, spliced in after a real
 * JPEG's SOI: what a phone writes, built by hand (the unit tests'
 * `photoBytes.testkit.ts` in JS). Big-endian TIFF: IFD0 (Make, Model, the
 * Exif pointer), then the Exif IFD (exposure, f-number, ISO, focal length).
 */
function withCameraExif(jpeg) {
  const ascii = (s) => Buffer.from(s + '\0', 'latin1')
  const make = ascii('Canon')
  const model = ascii('Canon EOS R6')
  // IFD0 at 8: 3 entries; its strings follow it; the Exif IFD after them.
  const ifd0At = 8
  const ifd0Len = 2 + 3 * 12 + 4
  const makeAt = ifd0At + ifd0Len
  const modelAt = makeAt + make.length
  const exifAt = modelAt + model.length
  const exifLen = 2 + 4 * 12 + 4
  const ratAt = exifAt + exifLen // three rationals, 8 bytes each
  const t = Buffer.alloc(ratAt + 24)
  t.write('MM\0*', 0, 'latin1')
  t.writeUInt32BE(ifd0At, 4)
  const entry = (at, tag, type, count, value) => {
    t.writeUInt16BE(tag, at)
    t.writeUInt16BE(type, at + 2)
    t.writeUInt32BE(count, at + 4)
    if (type === 3) t.writeUInt16BE(value, at + 8)
    else t.writeUInt32BE(value, at + 8)
  }
  t.writeUInt16BE(3, ifd0At)
  entry(ifd0At + 2, 0x010f, 2, make.length, makeAt)
  entry(ifd0At + 14, 0x0110, 2, model.length, modelAt)
  entry(ifd0At + 26, 0x8769, 4, 1, exifAt)
  make.copy(t, makeAt)
  model.copy(t, modelAt)
  t.writeUInt16BE(4, exifAt)
  entry(exifAt + 2, 0x829a, 5, 1, ratAt) // 1/250
  entry(exifAt + 14, 0x829d, 5, 1, ratAt + 8) // f/1.8
  entry(exifAt + 26, 0x8827, 3, 1, 400) // ISO
  entry(exifAt + 38, 0x920a, 5, 1, ratAt + 16) // 50mm
  for (const [i, [n, d]] of [[1, 250], [18, 10], [50, 1]].entries()) {
    t.writeUInt32BE(n, ratAt + i * 8)
    t.writeUInt32BE(d, ratAt + i * 8 + 4)
  }
  // A version 2 ICC profile whose one tag is its name.
  const name = Buffer.from('Display P3\0', 'latin1')
  const icc = Buffer.alloc(144 + 12 + name.length)
  icc.writeUInt32BE(icc.length, 0)
  icc.writeUInt32BE(0x02100000, 8)
  icc.write('mntrRGB XYZ ', 12, 'latin1')
  icc.write('acsp', 36, 'latin1')
  icc.writeUInt32BE(1, 128)
  icc.write('desc', 132, 'latin1')
  icc.writeUInt32BE(144, 136)
  icc.writeUInt32BE(12 + name.length, 140)
  icc.write('desc', 144, 'latin1')
  icc.writeUInt32BE(name.length, 152)
  name.copy(icc, 156)
  const seg = (marker, body) => {
    const h = Buffer.alloc(4)
    h.writeUInt16BE(marker, 0)
    h.writeUInt16BE(body.length + 2, 2)
    return Buffer.concat([h, body])
  }
  return Buffer.concat([
    jpeg.subarray(0, 2),
    seg(0xffe1, Buffer.concat([Buffer.from('Exif\0\0', 'latin1'), t])),
    seg(0xffe2, Buffer.concat([Buffer.from('ICC_PROFILE\0', 'latin1'), Buffer.from([1, 1]), icc])),
    jpeg.subarray(2)
  ])
}

/** The card, when one is on screen (the preview pane's included). */
const photoCard = (win) =>
  win.evaluate(() => {
    // The front viewer's: a warm tab behind it is inert, and draws its card too.
    const el = [...document.querySelectorAll('[data-photo-info]')].find((e) => e.getClientRects().length && !e.closest('[inert]'))
    if (!el) return null
    const rows = Object.fromEntries(
      [...el.querySelectorAll('[data-photo-info-row]')].map((r) => [r.getAttribute('data-photo-info-row'), r.querySelector('dd')?.textContent ?? ''])
    )
    return {
      state: el.getAttribute('data-photo-info'),
      line: el.querySelector('[data-photo-info-line]')?.textContent ?? '',
      none: el.querySelector('[data-photo-info-none]')?.textContent ?? '',
      rows
    }
  })
const photoInfoStored = (win) => win.evaluate(() => localStorage.getItem('prism.photoInfo'))

/** The picture's right-click menu, its rows' labels. */
async function imageMenuRows(win) {
  const layer = win.locator('[data-image-layer]').first()
  await layer.click({ button: 'right' })
  await win.waitForSelector('[role="menu"]', { timeout: 5000 })
  return win.locator('[role="menu"] [role="menuitem"]').evaluateAll((els) => els.map((e) => (e.textContent ?? '').trim()))
}

/**
 * THE I KEY'S PHOTO INFO CARD (#78; owner, 2026-11-01, the image pack spec
 * approved as recommended). A JPEG with a camera's EXIF and a Display P3
 * profile: I shows the card with its rows; Down to a PNG with none, the card
 * stays and says so; I hides it; the picture menu's Photo info row toggles
 * it; typing in a field never toggles it; with the Explorer list focused and
 * no name taking the letter, I toggles it in the preview pane; with two
 * picture tabs open I toggles it once, and a held I counts once; a comic page
 * (no file of its own) offers no row and I does nothing.
 */
async function photoInfoKeyScenario(fixtures) {
  console.log('the I key photo info card (#78)')
  if (!HAS_FFMPEG) {
    console.log(`  (no ffmpeg found (tried ${FFMPEG}), so there is no JPEG to put EXIF in: skipped)`)
    return
  }
  const dir = join(fixtures, 'photoinfo')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  const raw = join(dir, 'raw.jpg')
  execFileSync(FFMPEG, ['-y', '-loglevel', 'error', '-f', 'lavfi', '-i', 'testsrc=size=320x240', '-frames:v', '1', raw], { windowsHide: true, stdio: 'ignore' })
  writeFileSync(join(dir, 'cam.jpg'), withCameraExif(readFileSync(raw)))
  rmSync(raw, { force: true })
  writeFileSync(join(dir, 'plain.png'), clearPng())
  // The arrows step every file in the folder: the PNG comes straight after
  // the JPEG, the text file last.
  writeFileSync(join(dir, 'z-notes.txt'), 'beside the photos\n')
  copyFileSync(join(fixtures, 'comics', 'story.cbz'), join(dir, 'story.cbz'))
  const { app, win } = await launchWith(NO_INDEX, join(dir, 'cam.jpg'))
  try {
    await win.waitForSelector('[data-image-layer] img', { timeout: 15000 })
    await sleep(500)
    ok((await photoCard(win)) === null, 'no card until asked')

    // 1. I shows it, with what the camera wrote.
    await win.keyboard.press('i')
    const card = await until(async () => {
      const c = await photoCard(win)
      return c?.state === 'ready' && c.rows.Camera ? c : null
    }, 8000)
    ok(card?.rows.Camera === 'Canon EOS R6', `I shows the card with the camera (${card?.rows.Camera})`)
    ok(card?.rows.Exposure === '1/250s  f/1.8  ISO 400  50mm', `and the exposure (${card?.rows.Exposure})`)
    ok(card?.rows.Colour === 'Display P3', `and the colour profile's name (${card?.rows.Colour})`)
    ok(/^320 × 240 · 0\.1 MP · [\d.]+ (KB|B)$/.test(card?.line ?? ''), `the pixels line (${card?.line})`)
    const box = await win.evaluate(() => {
      const c = document.querySelector('[data-photo-info]')?.getBoundingClientRect()
      const s = document.querySelector('[data-image-layer]')?.parentElement?.getBoundingClientRect()
      return c && s ? { right: s.right - c.right, top: c.top - s.top } : null
    })
    ok(!!box && box.right >= 0 && box.right < 40 && box.top >= 0 && box.top < 40, `it sits in the stage's top-right corner (${JSON.stringify(box)})`)
    ok((await photoInfoStored(win)) === '1', 'and is remembered')
    await win.screenshot({ path: join(SHOTS, 'photo-info.png') })

    // 2. Down to a PNG with no camera data: the card stays and says so.
    await win.keyboard.press('ArrowDown')
    ok(await until(async () => (await viewing(win)).includes('plain.png'), 8000), 'Down steps to the PNG')
    const none = await until(async () => {
      const c = await photoCard(win)
      return c?.state === 'ready' && c.none ? c : null
    }, 8000)
    ok(none?.none === 'No camera details in this file', `the card stays and says there is nothing (${none?.none})`)
    ok(!!none && !('Camera' in none.rows), 'with no camera row from the last photo')
    ok(/^64 × 64 · /.test(none?.line ?? ''), `and this picture's pixels (${none?.line})`)

    // 3. I hides it.
    await win.keyboard.press('i')
    ok(await until(async () => (await photoCard(win)) === null, 3000), 'I again hides it')
    ok((await photoInfoStored(win)) === '0', 'and that is remembered too')

    // 4. The menu's row: present, unticked, and it toggles.
    let rows = await imageMenuRows(win)
    ok(rows.includes('Photo info'), `the picture's menu has Photo info (${rows.join(', ')})`)
    ok(rows.indexOf('Photo info') === rows.indexOf('Rotate') + 1, 'right after Rotate')
    await win.locator('[role="menu"] [role="menuitem"]:has-text("Photo info")').click()
    ok(await until(async () => (await photoCard(win)) !== null, 3000), 'the row turns the card on')
    const ticked = async () => {
      await win.locator('[data-image-layer]').first().click({ button: 'right' })
      await win.waitForSelector('[role="menu"]', { timeout: 5000 })
      const t = await win.locator('[role="menu"] [role="menuitem"]:has-text("Photo info") svg').count()
      return t
    }
    ok((await ticked()) === 1, 'and wears a tick while it is on')
    await win.locator('[role="menu"] [role="menuitem"]:has-text("Photo info")').click()
    ok(await until(async () => (await photoCard(win)) === null, 3000), 'picked again it turns the card off')

    // 5. Never while typing: the Explorer's address field takes the letter.
    await toList(win)
    await win.locator('[data-testid="browse-edit-path"]').click()
    const field = win.locator('.browse-path-form input')
    await field.waitFor({ timeout: 5000 })
    await field.press('End')
    await field.press('i')
    await sleep(300)
    ok((await photoInfoStored(win)) === '0', 'I typed in a field does not toggle the card')
    await win.keyboard.press('Escape')

    // 6. The Explorer list focused, cam.jpg previewed: no name starts with
    // "i", so the list's type-to-jump does not take the letter and the
    // viewer gets it, as R and F do (decision recorded in features.md).
    // The pane is opened if this profile has it shut, and shut again after.
    const paneShut = (await win.locator('.folder-browser[data-preview], .folder-browser [data-preview]').count()) === 0
    if (paneShut) await win.locator('.folder-browser button[aria-label="Preview pane"]').click()
    await listRow(win, 'cam.jpg').click()
    await sleep(800)
    const listHasFocus = await win.evaluate(() => !!document.activeElement?.closest('[data-testid="browse-list"]'))
    await win.keyboard.press('i')
    const inPreview = await until(async () => {
      const c = await photoCard(win)
      return c?.rows.Camera ? c : null
    }, 8000)
    ok(listHasFocus && !!inPreview, `with the list focused, I shows the card on the previewed photo (focus in list ${listHasFocus})`)
    await win.screenshot({ path: join(SHOTS, 'photo-info-preview.png') })
    await win.keyboard.press('i')
    ok(await until(async () => (await photoCard(win)) === null, 3000), 'and I hides it again')
    if (paneShut) await win.locator('.folder-browser button[aria-label="Preview pane"]').click()

    // 6b. Two picture tabs (review, 2026-11-01): every mounted picture
    // listens on the window and up to four stay mounted, so with two the
    // setting flipped twice and I did nothing. Tab 1 views cam.jpg, tab 2
    // plain.png; I on tab 2 toggles once. A held I (a key repeat) counts once.
    const tabSel = '[role="tablist"] [data-tab-role]:not([data-pinned]) [role="tab"]'
    const tabsBefore = await win.locator(tabSel).count()
    const firstTab = await win.locator(tabSel).evaluateAll((els) => els.findIndex((e) => e.getAttribute('aria-selected') === 'true'))
    await listRow(win, 'plain.png').click({ button: 'right' })
    await win.waitForSelector('[role="menu"]', { timeout: 5000 })
    await win.locator('[role="menuitem"]:has-text("Open in new tab")').click()
    ok(await until(async () => (await win.locator(tabSel).count()) === tabsBefore + 1, 5000), 'plain.png opens in a second tab')
    await win.locator(tabSel).nth(firstTab).click()
    await viewFile(win, 'cam.jpg')
    await win.locator(tabSel).last().click()
    ok(await until(async () => (await viewing(win)).includes('plain.png'), 8000), 'the second tab shows plain.png')
    await sleep(500)
    const pictures = await win.locator('[data-image-layer]').count()
    ok(pictures >= 2, `two pictures are mounted (${pictures})`)
    await win.keyboard.press('i')
    const two = await until(async () => {
      const c = await photoCard(win)
      return c?.state === 'ready' ? c : null
    }, 8000)
    ok(!!two && /^64 × 64 · /.test(two.line), `with two picture tabs, I shows the card on the one in front (${two?.line})`)
    ok((await photoInfoStored(win)) === '1', 'and the setting flipped once, to on')
    await win.keyboard.down('i')
    await win.keyboard.down('i')
    await win.keyboard.down('i')
    await win.keyboard.up('i')
    ok(await until(async () => (await photoCard(win)) === null, 3000), 'a held I hides it')
    await sleep(300)
    ok((await photoInfoStored(win)) === '0', `and the repeats did not flip it back (${await photoInfoStored(win)})`)
    await win.locator('[role="tablist"] [aria-label^="Close"]').last().click()
    ok(await until(async () => (await win.locator(tabSel).count()) === tabsBefore, 5000), 'the second tab closes')

    // 7. A comic page has no file of its own: no row, and I does nothing.
    await viewFile(win, 'story.cbz', 30000)
    await win.waitForSelector('[data-image-layer] img', { timeout: 20000 })
    await sleep(500)
    rows = await imageMenuRows(win)
    ok(!rows.includes('Photo info') && rows.includes('Rotate'), `a comic page's menu has no Photo info (${rows.join(', ')})`)
    await win.keyboard.press('Escape')
    await win.keyboard.press('i')
    await sleep(500)
    ok((await photoCard(win)) === null && (await photoInfoStored(win)) === '0', 'and I does nothing there')
  } finally {
    // The profile is shared: leave the card off for the scenarios after.
    await win.evaluate(() => localStorage.setItem('prism.photoInfo', '0')).catch(() => {})
    await app.close()
  }
}

/**
 * SAVE A COPY, TIDIED (#78; owner, 2026-11-01). A transparent PNG saved as
 * JPEG and as PNG through `PRISM_E2E_SAVE_TO` (never a native dialog): the
 * dialog would have opened in the photo's own folder with its name, the files
 * land, the JPEG's transparent corner is white, and the note names the file.
 * A read-only target says "Could not save the copy"; the photo itself as the
 * target is refused and left untouched; a cancel says nothing.
 */
async function imageSaveCopyScenario(fixtures) {
  console.log('Save a copy (#78)')
  const dir = join(fixtures, 'savecopy')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  const src = join(dir, 'clear.png')
  writeFileSync(src, clearPng())
  const srcBytes = readFileSync(src)
  writeFileSync(join(dir, 'notes.txt'), 'beside the picture\n')
  const ro = join(dir, 'locked.jpg')
  writeFileSync(ro, 'read-only')
  chmodSync(ro, 0o444)
  const { app, win } = await launchWith(NO_INDEX, src)
  const saveTo = (p) =>
    app.evaluate((_e, to) => {
      process.env.PRISM_E2E_SAVE_TO = to
    }, p)
  const asked = () => app.evaluate(() => globalThis.__e2eSaveDialog?.defaultPath ?? null)
  const note = () => win.locator('[data-copy-note]').first().textContent({ timeout: 200 }).catch(() => null)
  const save = async (format) => {
    await app.evaluate(() => {
      globalThis.__e2eSaveDialog = undefined
    })
    await win.locator('[data-image-layer]').first().click({ button: 'right' })
    await win.waitForSelector('[role="menu"]', { timeout: 5000 })
    await win.locator('[role="menu"] [role="menuitem"]:has-text("Save a copy")').hover()
    const item = win.locator('[role="menuitem"]').filter({ hasText: new RegExp(`^${format}$`) })
    if (!(await until(async () => (await item.count()) === 1, 4000))) {
      const seen = await win.locator('[role="menuitem"]').evaluateAll((els) => els.map((e) => `${(e.textContent ?? '').trim()}${e.disabled ? ' (disabled)' : ''}`))
      console.log(`  (no ${format} row; the menu shows: ${seen.join(', ')})`)
    }
    await item.click({ timeout: 5000 })
  }
  const noteGone = () => until(async () => (await note()) === null, 5000)
  try {
    await win.waitForSelector('[data-image-layer] img', { timeout: 15000 })
    await sleep(500)

    // JPEG: the photo's folder and name, the file, a white corner, the name in the note.
    const jpg = join(dir, 'out.jpg')
    await saveTo(jpg)
    await save('JPEG')
    const said = await until(async () => {
      const n = await note()
      return n && n.startsWith('Saved') ? n : null
    }, 8000)
    ok(said === 'Saved out.jpg', `the note names the saved file (${said})`)
    ok((await asked()) === join(dir, 'clear.jpg'), `the dialog would open in the photo's folder with its name (${await asked()})`)
    ok(existsSync(jpg) && readFileSync(jpg).subarray(0, 2).equals(Buffer.from([0xff, 0xd8])), 'the JPEG is on disk')
    if (HAS_FFMPEG) {
      const corner = execFileSync(FFMPEG, ['-loglevel', 'error', '-i', jpg, '-vf', 'format=rgb24,crop=1:1:0:0', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-'], { windowsHide: true })
      ok(corner.length === 3 && [...corner].every((v) => v > 240), `the transparent corner is white in the JPEG (${[...corner]})`)
    }
    await noteGone()

    // PNG: same folder; the same format would be the photo itself, so "copy".
    const png = join(dir, 'out.png')
    await saveTo(png)
    await save('PNG')
    ok((await until(async () => ((await note()) === 'Saved out.png' ? true : null), 8000)) === true, 'the PNG note names it')
    ok((await asked()) === join(dir, 'clear copy.png'), `the PNG's suggested name is not the photo's own (${await asked()})`)
    ok(existsSync(png) && readFileSync(png).subarray(1, 4).toString('latin1') === 'PNG', 'the PNG is on disk')
    await noteGone()

    // #474 (owner, 2026-11-01): the Explorer's five formats here too. WebP,
    // AVIF and JPEG XL are made in main from the canvas's PNG, alpha kept.
    for (const [label, ext, magic] of [
      ['WebP', 'webp', (b) => b.subarray(0, 4).toString('latin1') === 'RIFF' && b.subarray(8, 12).toString('latin1') === 'WEBP'],
      ['AVIF', 'avif', (b) => b.subarray(4, 12).toString('latin1') === 'ftypavif'],
      ['JPEG XL', 'jxl', (b) => (b[0] === 0xff && b[1] === 0x0a) || b.subarray(4, 8).toString('latin1') === 'JXL ']
    ]) {
      const to = join(dir, `out.${ext}`)
      await saveTo(to)
      await save(label)
      ok((await until(async () => ((await note()) === `Saved out.${ext}` ? true : null), 20000)) === true, `the ${label} note names it (${await note()})`)
      ok((await asked()) === join(dir, `clear.${ext}`), `the ${label} dialog would open on clear.${ext} (${await asked()})`)
      ok(existsSync(to) && magic(readFileSync(to)), `the ${label} is on disk, and is one`)
      if (HAS_FFMPEG && existsSync(to)) {
        const facts = probeCopy(to)
        ok(ext === 'avif' ? facts.length === 2 : /a/.test(facts[0].split(',')[2] ?? ''), `the ${label} keeps the alpha (${facts.join(' | ')})`)
      }
      await noteGone()
    }

    // A read-only target: the failure is said.
    await saveTo(ro)
    await save('JPEG')
    const failed = await until(async () => (await note()) ?? null, 8000)
    ok(failed === 'Could not save the copy', `a write that fails says so (${failed})`)
    ok(readFileSync(ro, 'utf8') === 'read-only', 'and the file there is untouched')
    await noteGone()

    // The photo itself: refused, untouched.
    await saveTo(src)
    await save('PNG')
    const refused = await until(async () => (await note()) ?? null, 8000)
    ok(refused === 'A copy cannot replace the original', `the photo itself is refused (${refused})`)
    ok(readFileSync(src).equals(srcBytes), 'and the original is untouched')
    await noteGone()

    // A cancel says nothing.
    await saveTo('')
    await save('JPEG')
    await sleep(1200)
    ok((await note()) === null, 'a cancel says nothing')
    await win.screenshot({ path: join(SHOTS, 'save-copy.png') })
  } finally {
    await app.evaluate(() => {
      delete process.env.PRISM_E2E_SAVE_TO
    }).catch(() => {})
    await app.close()
    chmodSync(ro, 0o666)
  }
}

/* ---------- SAVE COPIES AS (#474, owner 2026-11-01) ---------- */

const FFPROBE = FFMPEG.replace(/ffmpeg(\.exe)?$/i, 'ffprobe$1')

/** A JPEG with an EXIF orientation (6: turn right) and a maker's name, the
 *  shape a phone writes, so the copies can be checked for both. */
function withOrientationExif(jpeg, orientation, make) {
  const name = Buffer.from(make + '\0', 'latin1')
  const ifdLen = 2 + 2 * 12 + 4
  const t = Buffer.alloc(8 + ifdLen + name.length)
  t.write('II*\0', 0, 'latin1')
  t.writeUInt32LE(8, 4)
  t.writeUInt16LE(2, 8)
  t.writeUInt16LE(0x010f, 10) // Make, ASCII
  t.writeUInt16LE(2, 12)
  t.writeUInt32LE(name.length, 14)
  t.writeUInt32LE(8 + ifdLen, 18)
  t.writeUInt16LE(0x0112, 22) // Orientation, SHORT
  t.writeUInt16LE(3, 24)
  t.writeUInt32LE(1, 26)
  t.writeUInt16LE(orientation, 30)
  t.writeUInt32LE(0, 34)
  name.copy(t, 8 + ifdLen)
  const body = Buffer.concat([Buffer.from('Exif\0\0', 'latin1'), t])
  const head = Buffer.alloc(4)
  head.writeUInt16BE(0xffe1, 0)
  head.writeUInt16BE(body.length + 2, 2)
  return Buffer.concat([jpeg.subarray(0, 2), head, body, jpeg.subarray(2)])
}

/** ffprobe's facts of a copy: its streams' size and pixel format. */
const probeCopy = (file) =>
  execFileSync(FFPROBE, ['-v', 'error', '-show_entries', 'stream=width,height,pix_fmt', '-of', 'csv=p=0', file], { windowsHide: true })
    .toString()
    .trim()
    .split(/\r?\n/)

/** The Explorer at `dir`, these rows marked (Ctrl+click), right-click, Save
 *  copies as, `label`. */
async function saveCopiesOf(win, names, label) {
  const row = (n) => win.locator(`[data-testid="browse-list"] [data-browse-path$="\\\\${n}" i]`).first()
  await row(names[0]).locator('.browse-name-text').click()
  for (const n of names.slice(1)) await row(n).locator('.browse-name-text').click({ modifiers: ['Control'] })
  await sleep(250)
  await row(names[0]).locator('.browse-name-text').click({ button: 'right' })
  await win.waitForSelector('[role="menu"]', { timeout: 5000 })
  await win.locator('[role="menu"] [role="menuitem"]:has-text("Save copies as")').hover()
  const item = win.locator('[role="menuitem"]').filter({ hasText: new RegExp(`^${label}$`) })
  await until(async () => (await item.count()) === 1, 4000)
  await item.click({ timeout: 5000 })
}

const jobNote = (win) => win.locator('[data-job-note]').first().textContent({ timeout: 200 }).catch(() => null)
const marked = (win) =>
  win.evaluate(() =>
    [...document.querySelectorAll('[data-testid="browse-list"] [data-browse-path][aria-selected="true"]')].map(
      (r) => /[^\\]*$/.exec(r.getAttribute('data-browse-path') ?? '')?.[0]
    )
  )
/** Prism's job folders left in temp (`prism-copies-*`). */
const copiesTemps = () => readdirSync(tmpdir()).filter((n) => n.startsWith('prism-copies-'))

/**
 * SAVE COPIES AS, EVERY FORMAT (#474; owner, 2026-11-01): a clear PNG, a
 * phone JPEG turned by its EXIF and carrying a maker's name, and a text file,
 * marked in the Explorer and saved as JPEG, PNG, WebP, AVIF and JPEG XL. Each
 * copy is next to its original, under the format's extension, with its alpha
 * where the format has one (JPEG: on white), standing the way the viewer
 * shows it, and with no EXIF. A taken name becomes "name (2)" and the file
 * there is untouched; the text file is skipped and the done note says so;
 * what landed is what the list marks. Nothing is left in temp.
 */
async function batchCopiesScenario(fixtures) {
  console.log('Save copies as, every format (#474)')
  if (!HAS_FFMPEG) {
    console.log('  (no ffmpeg: skipped)')
    return
  }
  const dir = join(fixtures, 'batchcopies')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  writeFileSync(join(dir, 'clear.png'), clearPng())
  const plain = join(dir, 'plain.jpg')
  execFileSync(FFMPEG, ['-v', 'error', '-y', '-f', 'lavfi', '-i', 'color=c=0x3060c0:s=200x100', '-frames:v', '1', plain], { windowsHide: true })
  writeFileSync(join(dir, 'phone.jpg'), withOrientationExif(readFileSync(plain), 6, 'SecretCam'))
  rmSync(plain)
  writeFileSync(join(dir, 'notes.txt'), 'not a picture\n')
  // A name the JPEG copy would take, already there.
  writeFileSync(join(dir, 'clear.jpg'), 'someone else\'s file')
  const tempsBefore = copiesTemps().length
  const { app, win } = await launchWith(NO_INDEX, join(dir, 'notes.txt'))
  try {
    await explorerAt(win, dir)
    // The JPEG of phone.jpg would be phone.jpg itself: "phone (2).jpg".
    const formats = [
      ['JPEG', 'jpg', 'clear (2).jpg', 'phone (2).jpg'],
      ['PNG', 'png', 'clear (2).png', 'phone.png'],
      ['WebP', 'webp', 'clear.webp', 'phone.webp'],
      ['AVIF', 'avif', 'clear.avif', 'phone.avif'],
      ['JPEG XL', 'jxl', 'clear.jxl', 'phone.jxl']
    ]
    for (const [label, ext, clearName, phoneName] of formats) {
      await saveCopiesOf(win, ['clear.png', 'phone.jpg', 'notes.txt'], label)
      const note = await until(async () => {
        const n = await jobNote(win)
        return n && n.startsWith('Saved') ? n : null
      }, 60000)
      ok(note === 'Saved 2 copies, 1 skipped (not pictures)', `${label}: the done note (${note})`)
      const clear = join(dir, clearName)
      const phone = join(dir, phoneName)
      ok(existsSync(clear) && existsSync(phone), `${label}: both copies are next to their originals (${clearName}, ${phoneName})`)
      if (!existsSync(clear) || !existsSync(phone)) continue
      const clearFacts = probeCopy(clear)
      const phoneFacts = probeCopy(phone)
      // The phone photo is 200x100 turned right by its EXIF: the copy stands 100x200.
      ok(phoneFacts[0].startsWith('100,200'), `${label}: the copy stands as the viewer shows it (${phoneFacts[0]})`)
      ok(!readFileSync(phone).includes('SecretCam'), `${label}: no EXIF in the copy (the maker's name is gone)`)
      ok(!readFileSync(phone).includes(Buffer.from('Exif\0', 'latin1')), `${label}: no Exif block at all`)
      if (ext === 'jpg') {
        const corner = execFileSync(FFMPEG, ['-loglevel', 'error', '-i', clear, '-vf', 'format=rgb24,crop=1:1:0:0', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-'], { windowsHide: true })
        ok([...corner].every((v) => v > 240), `JPEG: the clear corner is white (${[...corner]})`)
        ok(readFileSync(join(dir, 'clear.jpg'), 'utf8') === 'someone else\'s file', 'JPEG: the taken name\'s file is untouched')
        ok(readFileSync(join(dir, 'phone.jpg')).includes('SecretCam'), 'JPEG: and so is the original phone.jpg')
      } else if (ext === 'avif') {
        // AVIF carries alpha as a second, grey picture.
        ok(clearFacts.length === 2 && /gray/.test(clearFacts[1]), `AVIF: the alpha is its second picture (${clearFacts.join(' | ')})`)
        ok(phoneFacts.length === 1, `AVIF: an opaque photo has none (${phoneFacts.join(' | ')})`)
      } else {
        ok(/a|pal8/.test(clearFacts[0].split(',')[2] ?? ''), `${label}: the alpha is kept (${clearFacts[0]})`)
      }
      if (ext === 'png') ok(readFileSync(join(dir, 'clear.png')).equals(clearPng()), 'PNG: the original is untouched (its copy is "clear (2).png")')
      const marks = await until(async () => {
        const m = await marked(win)
        return m.length === 2 ? m : null
      }, 10000)
      ok(
        !!marks && marks.includes(clearName) && marks.includes(phoneName),
        `${label}: the list marks what landed (${marks ?? (await marked(win))})`
      )
      if (ext === 'jpg') await win.screenshot({ path: join(SHOTS, 'save-copies-done.png') })
      ok(await until(async () => (await jobNote(win)) === null, 10000), `${label}: the note goes by itself`)
    }
    ok(copiesTemps().length === tempsBefore, `nothing is left in temp (${copiesTemps().join(', ')})`)
  } finally {
    await app.close().catch(() => {})
    rmSync(dir, { recursive: true, force: true })
  }
}

/**
 * SAVE COPIES AS, FROM AN IPHONE'S HEIC (#474; owner, 2026-11-01: "the real
 * fix for 400 iPhone HEICs"; review the same day: the HEIC route had no test
 * anywhere). Two HEICs (`assets/gradient.heic`, which carries an EXIF maker
 * "SecretCam"), an SVG and a text file, marked and saved as JPEG: both HEICs
 * get a JPEG beside them at their own size with no EXIF; the SVG is a picture
 * no copy can be made of ("could not be read"), the text file is not a
 * picture; and the job folder, which held the decoded JPEGs, is gone.
 */
async function batchCopiesHeicScenario(fixtures) {
  console.log('Save copies as, from HEIC (#474)')
  if (!HAS_FFMPEG) {
    console.log('  (no ffmpeg: skipped)')
    return
  }
  const dir = join(fixtures, 'batchcopies-heic')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  const heic = readFileSync(join(HERE, 'assets', 'gradient.heic'))
  ok(heic.includes('SecretCam'), 'the HEIC fixture carries its EXIF maker')
  writeFileSync(join(dir, 'IMG_0412.HEIC'), heic)
  writeFileSync(join(dir, 'IMG_0413.heic'), heic)
  writeFileSync(join(dir, 'logo.svg'), '<svg xmlns="http://www.w3.org/2000/svg" width="8" height="8"><rect width="8" height="8"/></svg>')
  writeFileSync(join(dir, 'notes.txt'), 'not a picture\n')
  const tempsBefore = copiesTemps().length
  const { app, win } = await launchWith(NO_INDEX, join(dir, 'notes.txt'))
  try {
    await explorerAt(win, dir)
    const started = Date.now()
    await saveCopiesOf(win, ['IMG_0412.HEIC', 'IMG_0413.heic', 'logo.svg', 'notes.txt'], 'JPEG')
    const note = await until(async () => {
      const n = await jobNote(win)
      return n && n.startsWith('Saved') ? n : null
    }, 60000)
    console.log(`  2 HEICs as JPEG in ${((Date.now() - started) / 1000).toFixed(1)} s`)
    ok(note === 'Saved 2 copies, 1 could not be read, 1 skipped (not pictures)', `the done note (${note})`)
    for (const name of ['IMG_0412.jpg', 'IMG_0413.jpg']) {
      const copy = join(dir, name)
      ok(existsSync(copy), `${name} is beside its HEIC`)
      if (!existsSync(copy)) continue
      const facts = probeCopy(copy)
      ok(facts[0].startsWith('640,480'), `${name}: the HEIC's own size (${facts[0]})`)
      ok(!readFileSync(copy).includes('SecretCam'), `${name}: no EXIF maker in the copy`)
      ok(!readFileSync(copy).includes(Buffer.from('Exif\0', 'latin1')), `${name}: no Exif block at all`)
      // The gradient's top-left is dark, its right edge red: a real decode.
      const px = execFileSync(FFMPEG, ['-loglevel', 'error', '-i', copy, '-vf', 'crop=1:1:639:0,format=rgb24', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-'], { windowsHide: true })
      ok(px[0] > 200 && px[1] < 60, `${name}: the picture is the HEIC's (top-right ${[...px]})`)
    }
    ok(readFileSync(join(dir, 'IMG_0412.HEIC')).equals(heic), 'the HEIC itself is untouched')
    // The decoded JPEGs live in the job's folder (each one dropped as soon as
    // its copy is made: copyJobs.test.ts), so the folder gone is all of them gone.
    ok(await until(() => copiesTemps().length === tempsBefore, 10000), `no job folder, so no decoded JPEG, is left in temp (${copiesTemps().join(', ')})`)
  } finally {
    await app.close().catch(() => {})
    rmSync(dir, { recursive: true, force: true })
  }
}

/**
 * SAVE COPIES AS, A REAL-SIZE BATCH (#474: "measure on 20+ real-size photos
 * that the job never freezes the UI"). 24 photos of 4032x3024 (a phone's 12
 * MP, noisy so they weigh what photos weigh), Ctrl+A, JPEG XL. While it runs
 * the page's frames and main's answers are timed: neither may stall. Then
 * the same folder as AVIF, Cancel part way: the copies made stay, no more
 * come, the note says it stopped, and nothing is left in temp.
 *
 * REAL PHOTOS (review, 2026-11-01: generated frames are not photos): with
 * PRISM_E2E_COPIES_PHOTOS naming a folder, its pictures (JPEG, HEIC, any
 * kind) are the batch instead, copied in as IMG_01.<ext> and on. Nothing of
 * them is kept or shown; the folder is removed after.
 */
async function batchCopiesLoadScenario(fixtures) {
  console.log('Save copies as, 24 real-size photos and Cancel (#474)')
  if (!HAS_FFMPEG) {
    console.log('  (no ffmpeg: skipped)')
    return
  }
  const dir = join(fixtures, 'batchcopies-load')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  const given = process.env.PRISM_E2E_COPIES_PHOTOS
  if (given) {
    const pics = readdirSync(given).filter((n) => /\.(jpe?g|heic|heif|png|webp|tiff?)$/i.test(n)).sort()
    pics.forEach((n, i) => copyFileSync(join(given, n), join(dir, `IMG_${String(i + 1).padStart(2, '0')}${n.slice(n.lastIndexOf('.')).toLowerCase()}`)))
  } else
    execFileSync(
      FFMPEG,
      ['-v', 'error', '-y', '-f', 'lavfi', '-i', 'testsrc2=s=4032x3024:r=1,noise=alls=24:allf=t', '-frames:v', '24', '-q:v', '3', join(dir, 'IMG_%02d.jpg')],
      { windowsHide: true }
    )
  writeFileSync(join(dir, 'notes.txt'), 'not a picture\n')
  const photos = readdirSync(dir).filter((n) => n.startsWith('IMG_'))
  const first = photos.sort()[0]
  const mb = photos.reduce((n, f) => n + statSync(join(dir, f)).size, 0) / 1048576
  console.log(`  ${photos.length} photos, ${mb.toFixed(0)} MB`)
  const tempsBefore = copiesTemps().length
  const { app, win } = await launchWith(NO_INDEX, join(dir, 'notes.txt'))
  const copies = (ext) => readdirSync(dir).filter((n) => n.endsWith(`.${ext}`))
  const markAll = async (label) => {
    const row = win.locator(`[data-testid="browse-list"] [data-browse-path$="\\\\${first}" i]`).first()
    await row.locator('.browse-name-text').click()
    await win.keyboard.press('Control+a')
    await sleep(300)
    await row.locator('.browse-name-text').click({ button: 'right' })
    await win.waitForSelector('[role="menu"]', { timeout: 5000 })
    await win.locator('[role="menu"] [role="menuitem"]:has-text("Save copies as")').hover()
    const item = win.locator('[role="menuitem"]').filter({ hasText: new RegExp(`^${label}$`) })
    await until(async () => (await item.count()) === 1, 4000)
    await item.click({ timeout: 5000 })
  }
  try {
    await explorerAt(win, dir)
    // The page's longest frame while the job runs.
    await win.evaluate(() => {
      const w = window
      w.__frames = { max: 0, n: 0, last: performance.now(), on: true }
      const tick = (t) => {
        const f = w.__frames
        if (!f.on) return
        f.max = Math.max(f.max, t - f.last)
        f.n += 1
        f.last = t
        requestAnimationFrame(tick)
      }
      requestAnimationFrame(tick)
    })
    const started = Date.now()
    await markAll('JPEG XL')
    // Main's longest answer, asked every 50 ms while the job runs.
    let mainMax = 0
    let note = null
    while (Date.now() - started < 240000) {
      const t = Date.now()
      await app.evaluate(() => 1)
      mainMax = Math.max(mainMax, Date.now() - t)
      note = await jobNote(win)
      if (note) break
      await sleep(50)
    }
    const took = (Date.now() - started) / 1000
    const { frameMax, frames } = await win.evaluate(() => {
      window.__frames.on = false
      return { frameMax: Math.round(window.__frames.max), frames: window.__frames.n }
    })
    ok(frames > took * 10, `the page drew all along (${frames} frames)`)
    console.log(`  JPEG XL: ${photos.length} copies in ${took.toFixed(1)} s; longest frame ${frameMax} ms, longest main answer ${mainMax} ms`)
    ok(note === `Saved ${photos.length} copies, 1 skipped (not pictures)`, `the done note (${note})`)
    ok(copies('jxl').length === photos.length, `every photo has its copy (${copies('jxl').length})`)
    ok(frameMax < 250, `the page never froze while it ran (longest frame ${frameMax} ms)`)
    ok(mainMax < 250, `nor main (longest answer ${mainMax} ms)`)
    ok(await until(async () => (await jobNote(win)) === null, 10000), 'the note goes')

    // AVIF, then Cancel once a few have landed.
    await markAll('AVIF')
    ok(await until(async () => copies('avif').length >= 3, 120000), `copies land (${copies('avif').length})`)
    const cancel = win.locator('[data-job-cancel]')
    ok((await cancel.count()) === 1, 'the chip has a Cancel while it runs')
    await win.screenshot({ path: join(SHOTS, 'save-copies-running.png') })
    await cancel.click()
    const stopped = await until(async () => {
      const n = await jobNote(win)
      return n && n.startsWith('Stopped') ? n : null
    }, 20000)
    const atStop = copies('avif').length
    ok(!!stopped && new RegExp(`^Stopped, saved ${atStop} cop(y|ies), 1 skipped \\(not pictures\\)$`).test(stopped), `the note says it stopped, and what it saved (${stopped})`)
    ok(atStop < photos.length, `Cancel stopped it short (${atStop} of ${photos.length})`)
    ok((await win.locator('[data-job-cancel]').count()) === 0, 'and the Cancel is gone')
    await sleep(3000)
    ok(copies('avif').length === atStop, `no copy lands after Cancel (${copies('avif').length})`)
    const marks = await marked(win)
    ok(marks.length === atStop && marks.every((m) => m.endsWith('.avif')), `the copies made before Cancel are marked (${marks.length})`)
    ok(await until(() => copiesTemps().length === tempsBefore, 10000), `nothing is left in temp (${copiesTemps().join(', ')})`)
  } finally {
    await app.close().catch(() => {})
    rmSync(dir, { recursive: true, force: true })
  }
}

/**
 * A REAL QUIT, for the log's last line: the harness's `app.close()` is
 * `app.exit(0)`, which skips will-quit, where the log writes its queue and
 * its `quit` line. Falls back to the harness's close after 15 s.
 */
async function quitForLog(app) {
  const child = app.process()
  await app.evaluate(({ app }) => app.quit()).catch(() => {})
  if (child.exitCode === null)
    await Promise.race([new Promise((done) => child.once('exit', done)), sleep(15000)])
  await app.close().catch(() => {})
}

/**
 * THE DIAGNOSTICS LOG (#322; owner, 2026-10-07: "implement some robust logging
 * and debugging into the program especially to catch stalls for example in
 * explorer or in general"). Each problem is made on purpose and then found in
 * <profile>\logs\diag.jsonl, the file the owner's "it stalled just now" is read
 * from: a 2.5 s busy loop in the page (a page-stall naming the script, the
 * crumbs before it, and the stack main took while it spun), a call main
 * answers after 600 ms (`e2e:slow-ipc`, --e2e only), a thrown error and a
 * rejected promise. Then Settings > Diagnostics: Open folder (recorded, never
 * opened, under --e2e), Mark, and Detailed logging kept across a relaunch.
 * The core's own scenario in Prism Terminal, on Prism's wiring.
 *
 * In `e2e:ui`, RUNNER-SAFE: the page, the log and the bridge are the
 * core's, so a core bump that breaks Prism's log is held here. The profile is
 * shared, so the log folder is emptied first and Detailed logging is taken
 * back off after (it lives in <profile>\diag.json, which every later
 * scenario would otherwise start verbose from).
 */
async function diagLogScenario(fixtures) {
  console.log('diagnostics log')
  rmSync(DIAG_DIR, { recursive: true, force: true })
  rmSync(join(PROFILE, 'diag.json'), { force: true })
  let app
  let win
  try {
    ;({ app, win } = await launch(join(fixtures, 'README.md')))
    const session = await diagHas((l) => l.k === 'session')
    ok(
      !!session && session.src === 'main' && session.e2e === true && session.verbose === false && typeof session.version === 'string' && session.pid > 0,
      `a session line opens the log (${JSON.stringify(session && { version: session.version, electron: session.electron, verbose: session.verbose })})`
    )
    // The Explorer tab in front: a tab-switch, from the page.
    await win.locator('[role="tablist"] [data-pinned] [role="tab"]').click()
    ok(!!(await diagHas((l) => l.k === 'crumb' && l.a === 'tab-switch' && l.src === 'page')), 'putting the Explorer tab in front is a tab-switch crumb, from the page')

    // A STALL: 2.5 s of the page's thread, started by a named timer.
    await win.evaluate(() => {
      setTimeout(function diagE2eBusy() {
        const end = performance.now() + 2500
        while (performance.now() < end) {
          /* spin */
        }
      }, 0)
    })
    const stall = await diagHas((l) => l.k === 'page-stall' && l.ms >= 2000)
    ok(!!stall && stall.src === 'page', `the busy loop is a page-stall (${stall?.ms} ms)`)
    const scripts = Array.isArray(stall?.scripts) ? stall.scripts : []
    ok(
      scripts.some((x) => x && (x.fn === 'diagE2eBusy' || /setTimeout/i.test(x.invoker ?? ''))),
      `with the script that ran named (${JSON.stringify(scripts)})`
    )
    const crumbs = Array.isArray(stall?.crumbs) ? stall.crumbs : []
    ok(crumbs.some((c) => c && c.a === 'tab-switch'), `and the crumbs said before it (${JSON.stringify(crumbs)})`)
    // The stack main took while the page spun, written because a page-stall
    // overlapping it arrived. It needs the Document-Policy header main adds.
    const stack = await diagHas((l) => l.k === 'page-stack', 6000)
    ok(
      !!stack && /diagE2eBusy/.test(stack.stack ?? '') && stack.ms >= 2000,
      `main took the spinning page's stack (${stack ? `${stack.ms} ms, ${String(stack.stack).split('\n')[1]?.trim()}` : 'none'})`
    )

    // A SLOW CALL: main answers after 600 ms.
    ok((await win.evaluate(() => window.prism.e2eSlowIpc())) === true, 'the slow call answers')
    const slow = await diagHas((l) => l.k === 'ipc-slow' && l.ch === 'e2e:slow-ipc')
    ok(!!slow && slow.ms >= 500 && slow.ok === true, `and is an ipc-slow line naming its channel (${slow?.ms} ms)`)

    // A MAIN LAG CARRIES ITS PROFILE (2026-10-12, lagProfiler.ts): 1.3 s of
    // main's own thread, in a named function, is a main-lag line naming a
    // .cpuprofile in the log folder whose stacks hold that function.
    await app.evaluate(() => {
      setTimeout(function diagE2eMainBusy() {
        const end = performance.now() + 1300
        while (performance.now() < end) {
          /* spin */
        }
      }, 0)
    })
    const lag = await diagHas((l) => l.k === 'main-lag' && l.ms >= 1000)
    if (lag) MADE_LAGS.add(lag.t)
    ok(!!lag && typeof lag.profile === 'string' && /^lag-.*\.cpuprofile$/.test(lag.profile), `the busy main is a main-lag naming its profile (${lag?.ms} ms, ${lag?.profile})`)
    const prof = lag?.profile ? join(DIAG_DIR, lag.profile) : ''
    const landed = await until(() => {
      try {
        return JSON.parse(readFileSync(prof, 'utf8'))
      } catch {
        return null
      }
    }, 10000, 100)
    ok(
      !!landed && Array.isArray(landed.nodes) && landed.nodes.some((n) => n?.callFrame?.functionName === 'diagE2eMainBusy'),
      `and the profile holds the function that spun (${landed ? `${landed.nodes?.length} nodes` : 'not written'})`
    )
    const said = await diagHas((l) => l.k === 'lag-profile' && l.profile === lag?.profile)
    ok(
      !!said && said.jsMs >= 1000 && /diagE2eMainBusy/.test(said.top?.[0] ?? ''),
      `and a lag-profile line says it was JavaScript, in that function (${JSON.stringify(said && { jsMs: said.jsMs, nativeMs: said.nativeMs, top: said.top?.[0] })})`
    )
    // AND A CHROMIUM TRACE (2026-10-27, nativeTrace.ts): the same lag names a
    // .trace.json whose toplevel events hold the 1.3 s task, the view a
    // freeze outside JavaScript needs.
    ok(typeof lag?.trace === 'string' && /^lag-.*\.trace\.json$/.test(lag.trace), `the main-lag names its Chromium trace (${lag?.trace})`)
    // Chromium writes the file from every process, which took more than 15 s
    // on the CI runner: wait for the dump's own `lag-trace` line, then read.
    const dumped = await diagHas((l) => l.k === 'lag-trace' && l.trace === lag?.trace, 90000)
    ok(!!dumped && !dumped.missing, `the trace dump finished (${JSON.stringify(dumped && { dumpMs: dumped.dumpMs, err: dumped.err })})`)
    const traced = (() => {
      try {
        return JSON.parse(readFileSync(join(DIAG_DIR, lag.trace), 'utf8'))
      } catch {
        return null
      }
    })()
    const longTask = (traced?.traceEvents ?? []).find((e) => String(e.cat).includes('toplevel') && e.dur >= 1_000_000)
    ok(!!longTask, `and the trace holds the long task (${traced ? `${traced.traceEvents?.length} events, ${longTask ? `${Math.round(longTask.dur / 1000)} ms ${longTask.name}` : 'none over 1 s'}` : 'not written'})`)

    // ERRORS: thrown in a timer, so it reaches the page's own handler (one
    // thrown inside evaluate is Playwright's), and a rejection nobody holds.
    await win.evaluate(() => {
      setTimeout(() => {
        throw new Error('diag-e2e-thrown')
      }, 0)
      void Promise.reject(new Error('diag-e2e-rejected'))
    })
    const thrown = await diagHas((l) => l.k === 'page-error' && /diag-e2e-thrown/.test(l.msg ?? ''))
    ok(!!thrown && /diag-e2e-thrown/.test(thrown.stack ?? ''), 'a thrown error is a page-error, with its stack')
    ok(!!(await diagHas((l) => l.k === 'page-rejection' && /diag-e2e-rejected/.test(l.msg ?? ''))), 'a rejected promise is a page-rejection')

    // THE PAGE: the folder, Mark, Detailed logging.
    const folderRow = await gotoPref(win, 'diag-folder')
    ok(!!(await diagHas((l) => l.k === 'crumb' && l.a === 'settings-page' && l.page === 'diagnostics')), 'opening the page is a crumb')
    const shownDir = await until(async () => ((await folderRow.textContent()) ?? '').includes(DIAG_DIR), 5000, 100)
    ok(!!shownDir, `Log files shows the folder the log is in (${await folderRow.textContent()})`)
    await folderRow.locator('button').click()
    const opened = await until(
      () => app.evaluate(() => globalThis.__e2eOpenedPaths ?? []).then((x) => x.some((p) => String(p).toLowerCase() === DIAG_DIR.toLowerCase()) || false),
      4000,
      100
    )
    ok(!!opened, 'Open folder opens that folder (recorded under --e2e)')
    const markAt = Date.now()
    await win.locator('[data-diag-mark]').click()
    ok(!!(await until(async () => await win.locator('[data-diag-mark] span').last().isVisible(), 2000, 50)), 'Mark says Marked')
    const mark = await diagHas((l) => l.k === 'mark')
    ok(!!mark && mark.src === 'page' && Math.abs(Date.parse(mark.t) - markAt) < 3000, `and stamps the moment in the log (${mark?.t})`)
    const sw = win.locator('[data-pref="diag-verbose"] [role="switch"]')
    ok((await sw.getAttribute('aria-checked')) === 'false', 'Detailed logging is off by default')
    await sw.click()
    ok(!!(await diagHas((l) => l.k === 'verbose' && l.on === true)), 'switching it on is a line')
    // The log's own diag: channels are never timed, so an app call.
    await win.evaluate(() => window.prism.appVersion())
    ok(!!(await diagHas((l) => l.k === 'ipc' && l.ch && !l.ch.startsWith('diag:'))), 'and every call is logged from then on')
    await quitForLog(app)
    app = null
    ok(readDiag().at(-1)?.k === 'quit', `a quit is the session's last line (${readDiag().at(-1)?.k})`)
    await sleep(900) // let the single-instance lock go

    // KEPT ACROSS A RELAUNCH: main reads it from <userData>\diag.json.
    ;({ app, win } = await launch(join(fixtures, 'README.md')))
    const second = await diagHas((l, i, all) => l.k === 'session' && all.slice(0, i).some((x) => x.k === 'session'))
    ok(!!second && second.verbose === true, `the next session starts detailed (${second?.verbose})`)
    await gotoPref(win, 'diag-verbose')
    ok(
      !!(await until(async () => (await win.locator('[data-pref="diag-verbose"] [role="switch"]').getAttribute('aria-checked')) === 'true', 5000, 100)),
      'and the switch says so'
    )
    // Off again through the switch, the way the owner would.
    await win.locator('[data-pref="diag-verbose"] [role="switch"]').click()
    ok(!!(await diagHas((l) => l.k === 'verbose' && l.on === false)), 'and switching it off is a line too')
    ok(readDiag().every((l) => !l.bad), 'every line in the file is one JSON object')
  } finally {
    await app?.close().catch(() => {})
    await sleep(600)
    // Whatever happened above, the scenarios after this one start quiet.
    rmSync(join(PROFILE, 'diag.json'), { force: true })
  }
}

/**
 * THE EXPLORER ON THE TIMELINE (#322): a folder opened by a double click is an
 * `open-folder` crumb saying where, why (`navigate`), how long and how many
 * rows; a column header pressed is a `sort` crumb naming the column and the
 * direction. These two are what a stall in the Explorer is read against.
 */
async function explorerDiagScenario(fixtures) {
  console.log('explorer diagnostics')
  const dir = join(fixtures, 'diag-folder')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(join(dir, 'inner'), { recursive: true })
  for (let i = 0; i < 6; i++) writeFileSync(join(dir, `file-${i}.txt`), 'x'.repeat(i + 1))
  rmSync(DIAG_DIR, { recursive: true, force: true })
  EXTRA_ENV = NO_INDEX
  let app
  let win
  let verboseOn = false
  try {
    const started = await launch(join(fixtures, 'README.md'))
    app = started.app
    win = started.win
    EXTRA_ENV = {}
    await win.locator('[role="tablist"] [data-pinned] [role="tab"]').click()
    await win.waitForSelector('[data-testid="browse-list"] .browse-row', { timeout: 10000 })
    const row = win.locator('[data-testid="browse-list"] [data-browse-path$="diag-folder"]')
    await row.waitFor({ timeout: 10000 })
    const target = await row.getAttribute('data-browse-path')
    await row.dblclick()
    ok(
      await until(async () => (await win.locator('[data-testid="browse-list"] [data-browse-path$=".txt"]').count()) === 6, 10000),
      'the folder opens'
    )
    const open = await diagHas((l) => l.k === 'crumb' && l.a === 'open-folder' && String(l.path ?? '').toLowerCase() === String(target).toLowerCase() && l.reason === 'navigate')
    ok(!!open, `opening it is an open-folder crumb, reason navigate (${JSON.stringify(open)})`)
    ok(!!open && typeof open.ms === 'number' && open.ms >= 0, `with how long the read took (${open?.ms} ms)`)
    ok(!!open && open.entries === 7, `and how many rows it has (${open?.entries}, 6 files and a folder)`)
    ok(!!open && typeof open.cached === 'boolean' && !open.unreadable, `and whether a cache painted first (${open?.cached})`)
    // ONE READ, ONE CRUMB (review of #322): the location effect joins the
    // navigation's read and must not say it again. Given time to.
    const key = String(target).toLowerCase()
    const opens = () => readDiag().filter((l) => l.k === 'crumb' && l.a === 'open-folder' && String(l.path ?? '').toLowerCase() === key)
    await sleep(800)
    ok(opens().length === 1, `the navigation is one open-folder crumb, not two (${opens().map((l) => l.reason).join(', ')})`)
    // Detailed logging, so a quick background read is written as well. By
    // the switch: the page keeps its own copy of the setting.
    await (await gotoPref(win, 'diag-verbose')).locator('[role="switch"]').click()
    verboseOn = true
    ok(!!(await diagHas((l) => l.k === 'verbose' && l.on === true)), 'Detailed logging is on')
    await win.click('[aria-label="Settings"]')
    await win.locator('[role="tablist"] [data-pinned] [role="tab"]').click()
    await win.locator('.folder-browser nav.browse-path .browse-crumb button[aria-current="location"]').waitFor({ timeout: 10000 })
    // The folder already shown, asked for again: no location moves, and the
    // navigation's marker must not swallow the next read's crumb.
    await win.locator('.folder-browser nav.browse-path .browse-crumb button[aria-current="location"]').click()
    ok(!!(await until(() => opens().filter((l) => l.reason === 'navigate').length === 2, 10000, 100)), 'asking for the folder on screen again is a navigate crumb')
    // FOCUS TRUSTS A LIVE WATCH (perf review, 2026-10-28, finding 10): the
    // folder is watched and was read a moment ago, so coming back to the
    // window reads nothing (it used to re-read every time, beside the watch).
    await win.evaluate(() => window.dispatchEvent(new Event('focus')))
    await sleep(1500)
    ok(!opens().some((l) => l.reason === 'focus'), `a focus on a watched, fresh folder reads nothing (${opens().map((l) => l.reason).join(', ')})`)
    const sortedBefore = readDiag().filter((l) => l.k === 'crumb' && l.a === 'sort').length
    await win.locator('.browse-list-area .browse-columns .browse-column-name').click()
    const sort = await diagHas((l, i, all) => l.k === 'crumb' && l.a === 'sort' && all.slice(0, i + 1).filter((x) => x.k === 'crumb' && x.a === 'sort').length > sortedBefore)
    ok(!!sort && sort.key === 'name' && (sort.direction === 'asc' || sort.direction === 'desc'), `pressing the Name header is a sort crumb (${JSON.stringify(sort && { key: sort.key, direction: sort.direction })})`)
  } finally {
    EXTRA_ENV = {}
    // The profile is shared and Detailed logging outlives a relaunch.
    if (verboseOn) await win?.evaluate(() => window.prism.diagSetVerbose(false)).catch(() => {})
    await app?.close().catch(() => {})
    rmSync(dir, { recursive: true, force: true })
  }
}

/* ----- the Stalls table (#322) ----- */

/**
 * EVERY RUN SAYS WHAT STALLED (#322; spec, "the e2e as a stall detector"):
 * each scenario starts on an empty log folder and its diagnostics log is read
 * after it, and every line of 1 s or more and every error is listed in a table
 * at the end. A REPORT, NOT A GATE: the exit code is the checks' alone, since
 * a slow line on a busy machine is a lead, not a failure. diagLog's own lines
 * are made on purpose and say so. Only the shared profile is read; a scenario
 * on a profile of its own (launchProbed's, Win+E windows) is not in it.
 */
const stalls = []
/** The `t` of each main-lag a scenario made on purpose (diagLog's busy main). */
const MADE_LAGS = new Set()
const DIAG_ERROR_KINDS = new Set(['page-error', 'page-rejection', 'main-error', 'main-rejection', 'ipc-error', 'gone', 'logger-error'])
function stallDetail(l, profiled) {
  const cut = (v) => String(v ?? '').replace(/\s+/g, ' ').slice(0, 70)
  if (l.k === 'page-stall') {
    const top = Array.isArray(l.scripts) ? l.scripts[0] : null
    return cut(top ? [top.fn, top.src, top.invoker].filter(Boolean).join(' ') : `blocking ${l.blocking ?? '?'}`)
  }
  if (l.k === 'page-stack') return cut(String(l.stack ?? '').split('\n').find((x) => /^\s*at /.test(x))?.trim())
  if (l.k === 'main-lag') {
    const calls = cut((Array.isArray(l.inflight) ? l.inflight : []).map((c) => `${c.ch} ${c.ms}${c.done ? ' done' : ''}`).join(', ') || 'nothing in flight')
    // The lag's CPU profile (lagProfiler.ts, 2026-10-12), copied to LAG_PROFILES.
    if (!l.profile) return calls
    // And what it said (lagSummary.ts): JavaScript and where, or time outside it.
    const what = profiled ? `js ${profiled.jsMs} ms${profiled.top?.[0] ? ` (${profiled.top[0]})` : ''}, outside js ${profiled.nativeMs} ms, ` : ''
    return `${calls} [${what}${l.profile}]`
  }
  if (l.k === 'ipc-slow' || l.k === 'ipc-error') return cut(`${l.ch}${l.err ? ` ${l.err}` : ''}`)
  if (l.k === 'gone') return cut(`${l.type} ${l.reason} ${l.exitCode}`)
  if (l.k === 'crumb') return cut(`${l.a} ${l.path ?? l.reason ?? ''}`)
  if (l.k === 'sort-slow') return cut(`${l.entries} rows, ${l.trigger}`)
  if (l.k === 'guard-slow') return cut(`${l.fn} ${l.paths} paths`)
  return cut(l.msg ?? l.err ?? l.path ?? '')
}
/** Where a run keeps the CPU profiles its main-lags wrote (lagProfiler.ts),
 *  as `<scenario>-lag-<time>.cpuprofile`; emptied at the start of a run. */
const LAG_PROFILES = join(ROOT, '.e2e', 'lag-profiles')
rmSync(LAG_PROFILES, { recursive: true, force: true })
function copyLagProfiles(scenario) {
  let names
  try {
    names = readdirSync(DIAG_DIR).filter((f) => /^lag-.*\.cpuprofile$/.test(f))
  } catch {
    return
  }
  if (!names.length) return
  mkdirSync(LAG_PROFILES, { recursive: true })
  for (const n of names) {
    try {
      copyFileSync(join(DIAG_DIR, n), join(LAG_PROFILES, `${scenario}-${n}`))
    } catch {
      /* a profile still being written is skipped */
    }
  }
}
function collectStalls(scenario) {
  copyLagProfiles(scenario)
  let files
  try {
    files = readdirSync(DIAG_DIR).filter((f) => f.startsWith('diag.jsonl'))
  } catch {
    return
  }
  const lines = []
  for (const f of files) {
    let text
    try {
      text = readFileSync(join(DIAG_DIR, f), 'utf8')
    } catch {
      continue
    }
    for (const raw of text.split('\n')) {
      if (!raw) continue
      try {
        lines.push(JSON.parse(raw))
      } catch {
        continue
      }
    }
  }
  // What each lag's profile said (`lag-profile`, lagSummary.ts), for its row.
  const said = new Map(lines.filter((l) => l.k === 'lag-profile').map((l) => [l.profile, l]))
  for (const l of lines) {
    const err = DIAG_ERROR_KINDS.has(l.k)
    if (!err && !(typeof l.ms === 'number' && l.ms >= 1000)) continue
    const made = scenario === 'diagLog' && (['page-stall', 'page-stack', 'page-error', 'page-rejection'].includes(l.k) || l.ch === 'e2e:slow-ipc' || (l.k === 'main-lag' && MADE_LAGS.has(l.t)))
    stalls.push({ scenario, kind: l.k === 'crumb' ? `crumb ${l.a}` : l.k, ms: typeof l.ms === 'number' ? l.ms : null, detail: stallDetail(l, said.get(l.profile)), expected: made })
  }
}

async function run(fn, gap = 900) {
  const name = fn.name.replace(/Scenario$/, '')
  if (!chosen(name)) return
  const before = failures
  const started = Date.now()
  // Each scenario's log is its own (#322): read after it, for the Stalls table.
  rmSync(DIAG_DIR, { recursive: true, force: true })
  try {
    await fn(fixtures)
  } catch (e) {
    failures += 1
    console.error(`scenario crashed (${name}):`, e)
  }
  const left = reapStrays()
  if (left) console.log(`  (reaped ${left} stray process(es) from ${name})`)
  collectStalls(name)
  results.push({ name, failed: failures > before, ms: Date.now() - started })
  await sleep(gap) // let the single-instance lock go
}

